import{z as A,x as B,o as n,c as p,q as t,j as l,D as E,d as i,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"链式复制","description":"","frontmatter":{"title":"链式复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chain-replication.md","filePath":"cs/chain-replication.md","lastUpdated":1791063341000}'),d={name:"cs/chain-replication.md"};function c(h,a,C,m,u,D){const r=B("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="链式复制" tabindex="-1">链式复制 <a class="header-anchor" href="#链式复制" aria-label="Permalink to &quot;链式复制&quot;">​</a></h1><div class="epigraph"><p>写从头流向尾，读只在尾。尾是提交点：尾上的值已沿链持久。头死了从后继接，尾死了前任升尾。</p><footer>—— 据 van Renesse and Schneider, Chain Replication for Supporting High Throughput and Availability, OSDI 2004 整理</footer></div><p>上一课<a href="/cs/primary-backup-failover">主备</a>是星形：主向所有备同步。缺口是<strong>吞吐</strong>：主的出站带宽随副本数线性涨。链式复制把副本排成一条线，主（头）只发给一个后继。本课不重写 fencing 纪元。后课 quorum 是另一套相交集合，不是链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 副本要线性一致读写。链：\\(H \\to \\cdots \\to T\\)。写请求到头，沿链转发，尾应答客户端（或沿链回 ack，视实现）。读到尾。因为每写必须流过整链才在尾可见，尾上的状态是已提交前缀；读尾得到线性化点在尾应答处。</p><p><span class="marginnote">数字实例：\\(n=5\\) 副本时，主备的主要同时发 4 份拷贝，出站带宽随 \\(n\\) 涨；链上每个节点只发 1 份给后继，头的带宽恒为 1。代价在延迟：写要走 4 跳 RTT，而星形只要 1 个 RTT 等最慢备——吞吐与延迟换了个方向。</span></p><p>缺口：链中段故障如何拆链再接，且不丢已在尾的写、不让未到尾的写冒充提交。需要配置主（通常小规模共识或目录）宣布新链。</p><p><span class="marginnote">CRAQ 让读分摊到链上节点但用版本问询，本课点名：纯 CR 读集中在尾，读吞吐是瓶颈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>头故障：后继变头，未完全传播的写由客户端重试（要幂等）。尾故障：前任变尾，其状态已是原尾的前缀，提交点不后退。中段：前驱改连后继，需保证 FIFO 与未完成写的重传。</p>',10)),(n(),l(s,null,{default:E(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20H%5B%22%E5%A4%B4%22%5D%0A%20%20H%20--%3E%20M%5B%22%E4%B8%AD%22%5D%0A%20%20M%20--%3E%20T%5B%22%E5%B0%BE%22%5D%0A%20%20T%20--%3E%20ACK%5B%22%E6%8F%90%E4%BA%A4%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20T%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与主备：主备主发送 \\(n-1\\) 份；链每节点发送 1 份。写延迟是链长倍的 RTT，不是星形的一个 RTT 等最慢备——权衡方向不同。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"线性化：写的线性化点可放在尾处理处；读尾看到的是已在尾的写集合前缀。若读头，会看见未提交写，破坏线性一致。历史与 Herlihy–Wing 对齐靠「只读尾」。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：线性一致（linearizable）就是「所有操作像发生在某个唯一的瞬间、全系统只有一种先后顺序」——并发程序看起来跑在一台机器上。提交点则是「历史从这里开始算数」的位置：链式复制里它几何上就压在尾节点，尾之前的链上值都还没作数。")],-1)),(n(),l(s,null,{default:E(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%7B%22%E5%93%AA%E4%B8%AA%E8%8A%82%E7%82%B9%E6%AD%BB%E4%BA%86%EF%BC%9F%22%7D%0A%20%20FAIL%20--%3E%7C%22%E5%A4%B4%22%7C%20HF%5B%22%E5%90%8E%E7%BB%A7%E5%8D%87%E5%A4%B4%EF%BC%9A%E6%9C%AA%E5%88%B0%E5%B0%BE%E7%9A%84%E5%86%99%E7%94%B1%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%B9%82%E7%AD%89%E9%87%8D%E8%AF%95%22%5D%0A%20%20FAIL%20--%3E%7C%22%E5%B0%BE%22%7C%20TF%5B%22%E5%89%8D%E4%BB%BB%E5%8D%87%E5%B0%BE%EF%BC%9A%E7%8A%B6%E6%80%81%E6%98%AF%E5%8E%9F%E5%B0%BE%E5%89%8D%E7%BC%80%EF%BC%8C%E6%8F%90%E4%BA%A4%E7%82%B9%E4%B8%8D%E5%90%8E%E9%80%80%22%5D%0A%20%20FAIL%20--%3E%7C%22%E4%B8%AD%E6%AE%B5%22%7C%20MF%5B%22%E5%89%8D%E9%A9%B1%E7%9B%B4%E6%8E%A5%E8%BF%9E%E5%90%8E%E7%BB%A7%EF%BC%9AFIFO%20%E9%87%8D%E4%BC%A0%E6%9C%AA%E5%AE%8C%E6%88%90%E5%86%99%22%5D%0A%20%20HF%20--%3E%20CM%5B%22%E9%85%8D%E7%BD%AE%E4%B8%BB%E5%AE%A3%E5%B8%83%E6%96%B0%E9%93%BE%22%5D%0A%20%20TF%20--%3E%20CM%0A%20%20MF%20--%3E%20CM%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>配置主自己必须强一致，否则两条链同时有效，等价双主。链再长也把 CAP 的 C 押在配置面上。故障时缩短链，可用副本变少，直到配置主补节点。</p><p><span class="marginnote">常见误区：初学者容易觉得「读哪个副本都行，只要数据在」。链式复制里读头会看见还没流到尾的写——那是不算数的未提交值。想要读扩展又保持一致，得像 CRAQ 那样用版本号向头问询，而不是随便挑一个节点读。</span></p><p>本课不把 Kafka ISR、日志分段写成链式复制定理：它们借鉴「提交点在高水位」，拓扑不是单链转发每个字节。后课日志会自己讲。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CRAQ 协议全文，不引入异地多链。不把链表数据结构当本课。后课默认：要线性一致且写带宽不随 \\(n\\) 在主上爆炸，链是候选；要读扩展要想 CRAQ 或换 quorum。法定人数下一课从相交集合重新开始。</p><p>链的提交点几何上就是尾。改读位置就改一致性档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写从头到尾，读尾；尾是提交点。</li><li>中段故障靠配置主重链；配置面仍须强一致。</li><li>写带宽省在头，读集中在尾。</li><li>出处：van Renesse and Schneider, OSDI 2004。</li></ul>',8))])}const f=A(d,[["render",c]]);export{F as __pageData,f as default};
